def get_crypto_price(symbol, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0370000" if __import__("os").path.isdir("./environment_mix/0370000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now_dt.isoformat().replace("+00:00", "Z")

    logs_name = None
    for cand in ("request_logs.json", "requests.json", "usage_logs.json", "audit_logs.json"):
        if os.path.exists(os.path.join(_DB, cand)):
            logs_name = cand
            break

    def _append_log(status, error_code=None, asset_id=None, symbol_resolved=None):
        if not logs_name:
            return
        logs = _load(logs_name)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "get-crypto-price",
            "status": status,
            "error_code": error_code,
            "symbol": symbol,
            "symbol_resolved": symbol_resolved,
            "asset_id": asset_id,
            "timestamp": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(logs_name, logs)

    def _rate_limit_check():
        if not logs_name:
            return None
        logs = _load(logs_name)
        if not isinstance(logs, list):
            return None
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            s = ts.strip()
            try:
                if s.endswith("Z"):
                    dt = datetime.datetime.fromisoformat(s[:-1] + "+00:00")
                else:
                    dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    rl = _rate_limit_check()
    if rl is not None:
        _append_log("error", error_code="RATE_LIMIT")
        return rl

    if not isinstance(symbol, str) or not symbol.strip():
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string")

    sym_in = symbol.strip()
    sym_upper = sym_in.upper()

    assets = _load("crypto_assets.json")
    if not isinstance(assets, list):
        assets = []
    resolved = None
    for a in assets:
        if not isinstance(a, dict):
            continue
        if str(a.get("symbol", "")).upper() == sym_upper:
            if a.get("status") == "active" and a.get("is_active") is True:
                resolved = a
                break
    if not resolved:
        _append_log("error", error_code="NOT_FOUND", symbol_resolved=sym_upper)
        return _err("NOT_FOUND", "Asset not found or not active", symbol=sym_in)

    asset_id = resolved.get("id")

    snaps = _load("price_snapshots.json")
    if not isinstance(snaps, list):
        snaps = []

    def _parse_dt(s):
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            else:
                dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    best = None
    best_dt = None
    for r in snaps:
        if not isinstance(r, dict):
            continue
        if r.get("asset_id") != asset_id:
            continue
        if r.get("currency") != "USD":
            continue
        if r.get("ingestion_status") not in ("complete", "partial"):
            continue
        dt = _parse_dt(r.get("observed_at"))
        if dt is None:
            continue
        if best is None or dt > best_dt:
            best = r
            best_dt = dt

    if best is None:
        _append_log("error", error_code="NOT_FOUND", asset_id=asset_id, symbol_resolved=sym_upper)
        return _err("NOT_FOUND", "No current snapshot available", symbol=sym_in, asset_id=asset_id)

    _append_log("ok", asset_id=asset_id, symbol_resolved=sym_upper)
    return {
        "asset": {
            "id": resolved.get("id"),
            "symbol": resolved.get("symbol"),
            "name": resolved.get("name"),
        },
        "snapshot": best,
    }

def get_market_analysis(symbol, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0370000" if __import__("os").path.isdir("./environment_mix/0370000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status_code = "ok"
    try:
        # Rate-limit / usage log
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        cutoff = now - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs:
            ts = r.get("timestamp")
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None) if isinstance(ts, str) else None
            except Exception:
                dt = None
            if dt and dt >= cutoff:
                recent += 1
        if recent >= 120:
            status_code = "RATE_LIMIT"
            return _err("RATE_LIMIT", "Rate limit exceeded")

        # Validate symbol
        if symbol is None or not isinstance(symbol, str) or not symbol.strip():
            status_code = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "symbol is required and must be a non-empty string")
        sym_in = symbol.strip()
        if len(sym_in) < 2 or len(sym_in) > 10:
            status_code = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "symbol length must be between 2 and 10")

        # Resolve asset
        assets = _load("crypto_assets.json")
        if not isinstance(assets, list):
            assets = []
        asset = None
        for a in assets:
            if isinstance(a, dict) and isinstance(a.get("symbol"), str) and a["symbol"].lower() == sym_in.lower():
                asset = a
                break
        if not asset or asset.get("status") != "active" or asset.get("is_active") is not True:
            status_code = "NOT_FOUND"
            return _err("NOT_FOUND", "Asset not found or not active", symbol=sym_in)

        metrics = _load("exchange_market_metrics.json")
        if not isinstance(metrics, list):
            metrics = []

        # For each (asset_id, exchange_id), pick latest observed_at where status='valid' and currency='USD'
        latest_by_pair = {}
        for m in metrics:
            if not isinstance(m, dict):
                continue
            if m.get("asset_id") != asset.get("id"):
                continue
            if m.get("currency") != "USD":
                continue
            if m.get("status") != "valid":
                continue
            obs = m.get("observed_at")
            if not isinstance(obs, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(obs.replace("Z", "+00:00"))
            except Exception:
                continue
            key = (m.get("asset_id"), m.get("exchange_id"))
            prev = latest_by_pair.get(key)
            if prev is None or dt > prev[0]:
                latest_by_pair[key] = (dt, m)

        selected = [v[1] for v in latest_by_pair.values()]
        if not selected:
            status_code = "NOT_FOUND"
            return _err("NOT_FOUND", "No market metrics available for this asset", symbol=asset.get("symbol"))

        # Sum volume per exchange_id
        vol_by_exchange = {}
        for m in selected:
            exid = m.get("exchange_id")
            vol = m.get("volume_24h")
            if not isinstance(vol, (int, float)) or vol < 0:
                # Skip invalid volume rows; constraints say >=0, but don't crash if bad data exists
                continue
            vol_by_exchange[exid] = vol_by_exchange.get(exid, 0.0) + float(vol)

        if not vol_by_exchange:
            status_code = "NOT_FOUND"
            return _err("NOT_FOUND", "No valid market volumes available for this asset", symbol=asset.get("symbol"))

        exchanges = _load("exchanges.json")
        if not isinstance(exchanges, list):
            exchanges = []
        ex_by_id = {e.get("id"): e for e in exchanges if isinstance(e, dict) and e.get("id")}

        # Top exchanges (server-side max 10)
        top_max = 10
        ranked = sorted(vol_by_exchange.items(), key=lambda kv: kv[1], reverse=True)[:top_max]
        total_volume = sum(v for _, v in ranked)

        top_list = []
        for exid, vol in ranked:
            ex = ex_by_id.get(exid, {}) if isinstance(ex_by_id.get(exid), dict) else {}
            item = {
                "exchange": {
                    "id": exid,
                    "code": ex.get("code"),
                    "name": ex.get("name"),
                    "status": ex.get("status"),
                },
                "volume_24h_usd": vol,
            }
            if total_volume > 0:
                item["share"] = vol / total_volume
            else:
                item["share"] = 0.0
            top_list.append(item)

        # Determine a "latest_observed_at" across selected metrics (max dt)
        latest_dt = None
        for (dt, m) in latest_by_pair.values():
            if latest_dt is None or dt > latest_dt:
                latest_dt = dt
        latest_observed_at = latest_dt.isoformat().replace("+00:00", "Z") if latest_dt else None

        return {
            "asset": {"id": asset.get("id"), "symbol": asset.get("symbol"), "name": asset.get("name")},
            "currency": "USD",
            "latest_observed_at": latest_observed_at,
            "top_exchanges": top_list,
            "total_top_volume_24h_usd": total_volume,
            "top_limit": top_max,
        }
    finally:
        try:
            latency_ms = int((time.time() - t0) * 1000)
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "get-market-analysis",
                "status": status_code,
                "latency_ms": latency_ms,
                "timestamp": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

def get_historical_analysis(symbol, interval=None, days=None, **_extra):
    import json, os, datetime, time, uuid, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0370000" if __import__("os").path.isdir("./environment_mix/0370000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status_code = "ok"
    try:
        # Rate-limit / usage log
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        cutoff = now - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs:
            ts = r.get("timestamp")
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None) if isinstance(ts, str) else None
            except Exception:
                dt = None
            if dt and dt >= cutoff:
                recent += 1
        if recent >= 120:
            status_code = "RATE_LIMIT"
            return _err("RATE_LIMIT", "Rate limit exceeded")

        # Validate symbol
        if symbol is None or not isinstance(symbol, str) or not symbol.strip():
            status_code = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "symbol is required and must be a non-empty string")
        sym_in = symbol.strip()
        if len(sym_in) < 2 or len(sym_in) > 10:
            status_code = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "symbol length must be between 2 and 10")

        # Validate interval
        allowed = {"m5", "m15", "m30", "h1", "h2", "h6", "h12", "d1"}
        if interval is None:
            interval = "h1"
        if not isinstance(interval, str) or interval not in allowed:
            status_code = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "interval must be one of m5,m15,m30,h1,h2,h6,h12,d1")

        # Validate/coerce days
        if days is None:
            days_i = 7
        else:
            if isinstance(days, bool):
                status_code = "VALIDATION_ERROR"
                return _err("VALIDATION_ERROR", "days must be an integer between 1 and 30")
            if isinstance(days, (int, float)):
                if isinstance(days, float) and (math.isnan(days) or math.isinf(days)):
                    status_code = "VALIDATION_ERROR"
                    return _err("VALIDATION_ERROR", "days must be an integer between 1 and 30")
                if int(days) != days:
                    status_code = "VALIDATION_ERROR"
                    return _err("VALIDATION_ERROR", "days must be an integer between 1 and 30")
                days_i = int(days)
            else:
                status_code = "VALIDATION_ERROR"
                return _err("VALIDATION_ERROR", "days must be an integer between 1 and 30")
        if days_i < 1 or days_i > 30:
            status_code = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "days must be between 1 and 30")

        # Resolve asset
        assets = _load("crypto_assets.json")
        if not isinstance(assets, list):
            assets = []
        asset = None
        for a in assets:
            if isinstance(a, dict) and isinstance(a.get("symbol"), str) and a["symbol"].lower() == sym_in.lower():
                asset = a
                break
        if not asset or asset.get("status") != "active" or asset.get("is_active") is not True:
            status_code = "NOT_FOUND"
            return _err("NOT_FOUND", "Asset not found or not active", symbol=sym_in)

        start_window = now - datetime.timedelta(days=days_i)

        candles = _load("candles.json")
        if not isinstance(candles, list):
            candles = []

        rows = []
        for c in candles:
            if not isinstance(c, dict):
                continue
            if c.get("asset_id") != asset.get("id"):
                continue
            if c.get("currency") != "USD":
                continue
            if c.get("interval") != interval:
                continue
            if c.get("status") not in ("valid", "corrected"):
                continue
            sa = c.get("start_at")
            if not isinstance(sa, str):
                continue
            try:
                sa_dt = datetime.datetime.fromisoformat(sa.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if sa_dt < start_window or sa_dt > now:
                continue
            rows.append((sa_dt, c))

        rows.sort(key=lambda x: x[0])
        candle_list = [c for _, c in rows]

        if not candle_list:
            status_code = "NOT_FOUND"
            return _err("NOT_FOUND", "No candles available for requested window", symbol=asset.get("symbol"), interval=interval, days=days_i)

        return {
            "asset": {"id": asset.get("id"), "symbol": asset.get("symbol"), "name": asset.get("name")},
            "currency": "USD",
            "interval": interval,
            "days": days_i,
            "window_start": start_window.replace(microsecond=0).isoformat() + "Z",
            "window_end": now.replace(microsecond=0).isoformat() + "Z",
            "candles": candle_list,
            "count": len(candle_list),
        }
    finally:
        try:
            latency_ms = int((time.time() - t0) * 1000)
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "get-historical-analysis",
                "status": status_code,
                "latency_ms": latency_ms,
                "timestamp": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

def list_crypto_assets(q=None, symbol=None, status=None, is_active=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0370000" if __import__("os").path.isdir("./environment_mix/0370000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now_dt.isoformat().replace("+00:00", "Z")

    logs_name = None
    for cand in ("request_logs.json", "requests.json", "usage_logs.json", "audit_logs.json"):
        if os.path.exists(os.path.join(_DB, cand)):
            logs_name = cand
            break

    def _append_log(status, error_code=None):
        if not logs_name:
            return
        logs = _load(logs_name)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "list-crypto-assets",
            "status": status,
            "error_code": error_code,
            "timestamp": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(logs_name, logs)

    def _rate_limit_check():
        if not logs_name:
            return None
        logs = _load(logs_name)
        if not isinstance(logs, list):
            return None
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            s = ts.strip()
            try:
                if s.endswith("Z"):
                    dt = datetime.datetime.fromisoformat(s[:-1] + "+00:00")
                else:
                    dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    rl = _rate_limit_check()
    if rl is not None:
        _append_log("error", error_code="RATE_LIMIT")
        return rl

    # Relaxed validation: accept non-string q by coercing to string (audit defect)
    if q is not None and not isinstance(q, str):
        try:
            q = str(q)
        except Exception:
            _append_log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "q must be a string")

    if symbol is not None:
        if not isinstance(symbol, str):
            try:
                symbol = str(symbol)
            except Exception:
                _append_log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "symbol must be a string when provided")
        if not symbol.strip():
            _append_log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "symbol must be a non-empty string when provided")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "disabled", "merged"):
            _append_log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of active, disabled, merged")

    if is_active is not None and not isinstance(is_active, bool):
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_active must be a boolean")

    if limit is None:
        limit_i = 50
    else:
        if not isinstance(limit, int):
            _append_log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 200:
            _append_log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
        limit_i = limit

    if cursor is not None and not isinstance(cursor, str):
        try:
            cursor = str(cursor)
        except Exception:
            _append_log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string when provided")

    rows = _load("crypto_assets.json")
    if not isinstance(rows, list):
        rows = []

    # Deterministic order for cursor pagination
    def _key(r):
        return (str(r.get("symbol", "")).upper(), str(r.get("id", "")))
    rows_sorted = [r for r in rows if isinstance(r, dict)]
    rows_sorted.sort(key=_key)

    # Apply cursor as "start after id"
    start_idx = 0
    if cursor:
        for i, r in enumerate(rows_sorted):
            if r.get("id") == cursor:
                start_idx = i + 1
                break

    q_l = q.strip().lower() if isinstance(q, str) and q.strip() else None
    sym_u = symbol.strip().upper() if isinstance(symbol, str) and symbol.strip() else None

    filtered = []
    for r in rows_sorted[start_idx:]:
        if sym_u is not None and str(r.get("symbol", "")).upper() != sym_u:
            continue
        if status is not None and r.get("status") != status:
            continue
        if is_active is not None and r.get("is_active") is not is_active:
            continue
        if q_l is not None:
            s = (str(r.get("symbol", "")) + " " + str(r.get("name", ""))).lower()
            if q_l not in s:
                continue
        filtered.append(r)

    total_after_cursor = len(filtered)
    page = filtered[:limit_i]
    has_more = total_after_cursor > len(page)
    next_cursor = page[-1].get("id") if has_more and page else None

    _append_log("ok")
    return {
        "data": page,
        "meta": {
            "limit": limit_i,
            "total": total_after_cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
        }
    }

def get_crypto_asset(id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0370000" if __import__("os").path.isdir("./environment_mix/0370000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _parse_dt(v):
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v:
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    # ---- request log + rate limit/quota enforcement (if collection exists) ----
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []

    window_s = 60
    daily_s = 86400
    rate_limit = 60
    daily_quota = 10000
    principal = "ambient"

    cutoff_rate = now - datetime.timedelta(seconds=window_s)
    cutoff_day = now - datetime.timedelta(seconds=daily_s)
    rate_count = 0
    day_count = 0
