        if ts >= cutoff_rate:
            rate_count += 1
        if ts >= cutoff_day:
            day_count += 1

    if day_count >= daily_quota:
        logs.append({
            "id": f"rl_{int(time.time()*1000)}",
            "timestamp": now.isoformat().replace("+00:00", "Z"),
            "endpoint": "get-crypto-asset",
