            "asset_id": asset_id,
            "timestamp": now_iso,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(logs_name, logs)

    def _rate_limit_check():
        if not logs_name:
            return None
        logs = _load(logs_name)
        if not isinstance(logs, list):
            return None
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            s = ts.strip()
            try:
                if s.endswith("Z"):
                    dt = datetime.datetime.fromisoformat(s[:-1] + "+00:00")
                else:
                    dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        if cnt >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    rl = _rate_limit_check()
    if rl is not None:
        _append_log("error", error_code="RATE_LIMIT")
        return rl

    if not isinstance(symbol, str) or not symbol.strip():
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "symbol is required")
    if not isinstance(name, str) or not name.strip():
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name is required")

    sym = symbol.strip()
    sym_u = sym.upper()
    if sym != sym_u:
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "symbol must be uppercase")
    if len(sym_u) < 2 or len(sym_u) > 10:
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "symbol length must be between 2 and 10")
    if not re.fullmatch(r"[A-Z0-9]+", sym_u):
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "symbol must be alphanumeric uppercase")

    if id is not None and (not isinstance(id, str) or not id.strip()):
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id must be a non-empty string when provided")
    if coingecko_id is not None and (not isinstance(coingecko_id, str) or not coingecko_id.strip()):
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "coingecko_id must be a non-empty string when provided")
    if is_active is not None and not isinstance(is_active, bool):
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_active must be a boolean when provided")
    if status is not None and (not isinstance(status, str) or status not in ("active", "disabled", "merged")):
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of active, disabled, merged")
    if merged_into_asset_id is not None and (not isinstance(merged_into_asset_id, str) or not merged_into_asset_id.strip()):
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "merged_into_asset_id must be a non-empty string when provided")

    assets = _load("crypto_assets.json")
    if not isinstance(assets, list):
        assets = []

    by_id = {a.get("id"): a for a in assets if isinstance(a, dict) and isinstance(a.get("id"), str)}
    existing = by_id.get(id) if id else None

    # Uniqueness checks (symbol always unique; coingecko_id unique when non-null)
    for a in assets:
        if not isinstance(a, dict):
            continue
        if existing is not None and a is existing:
            continue
        if str(a.get("symbol", "")).upper() == sym_u:
            _append_log("error", error_code="CONFLICT", asset_id=(existing or {}).get("id"))
            return _err("CONFLICT", "symbol already exists", symbol=sym_u, existing_id=a.get("id"))
        if coingecko_id is not None and a.get("coingecko_id") == coingecko_id:
            _append_log("error", error_code="CONFLICT", asset_id=(existing or {}).get("id"))
            return _err("CONFLICT", "coingecko_id already exists", coingecko_id=coingecko_id, existing_id=a.get("id"))

    # Determine desired fields
    desired_status = status if status is not None else (existing.get("status") if existing else "active")
    desired_is_active = is_active if is_active is not None else (existing.get("is_active") if existing else True)

    # Constraint: is_active=true implies status='active'
    if desired_is_active is True and desired_status != "active":
        _append_log("error", error_code="VALIDATION_ERROR", asset_id=(existing or {}).get("id"))
        return _err("VALIDATION_ERROR", "is_active=true requires status='active'")

    if desired_status == "merged":
        if not merged_into_asset_id:
            _append_log("error", error_code="VALIDATION_ERROR", asset_id=(existing or {}).get("id"))
            return _err("VALIDATION_ERROR", "merged_into_asset_id is required when status='merged'")
        if merged_into_asset_id == (existing.get("id") if existing else id):
            _append_log("error", error_code="VALIDATION_ERROR", asset_id=(existing or {}).get("id"))
            return _err("VALIDATION_ERROR", "merged_into_asset_id cannot equal the asset id")
        if merged_into_asset_id not in by_id:
            _append_log("error", error_code="NOT_FOUND", asset_id=(existing or {}).get("id"))
            return _err("NOT_FOUND", "merged_into_asset_id not found", merged_into_asset_id=merged_into_asset_id)

    # Lifecycle transitions
    transitions = {
        "active": set(["disabled", "merged"]),
        "disabled": set(["active"]),
        "merged": set([]),
    }

    if existing is None:
        # create
        new_id = id.strip() if isinstance(id, str) and id.strip() else ("cpa_" + uuid.uuid4().hex)
        if new_id in by_id:
            _append_log("error", error_code="CONFLICT")
            return _err("CONFLICT", "id already exists", id=new_id)
        row = {
            "id": new_id,
            "symbol": sym_u,
            "name": name.strip(),
            "coingecko_id": coingecko_id.strip() if isinstance(coingecko_id, str) else None,
            "is_active": bool(desired_is_active),
            "status": desired_status,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        # preserve extra field if used by callers (not in schema, but allowed by tool)
        if merged_into_asset_id is not None:
            row["merged_into_asset_id"] = merged_into_asset_id.strip()
        assets.append(row)
        _save("crypto_assets.json", assets)
        _append_log("ok", asset_id=new_id)
        return {"data": row, "created": True}
    else:
        current_status = existing.get("status")
        if status is not None and status != current_status:
            if current_status not in transitions or status not in transitions[current_status]:
                _append_log("error", error_code="INVALID_TRANSITION", asset_id=existing.get("id"))
                return _err("INVALID_TRANSITION", "Illegal status transition", from_status=current_status, to_status=status)

        # apply updates
        existing["symbol"] = sym_u
        existing["name"] = name.strip()
        if coingecko_id is not None:
            existing["coingecko_id"] = coingecko_id.strip()
        elif "coingecko_id" not in existing:
            existing["coingecko_id"] = None
        if is_active is not None:
            existing["is_active"] = bool(is_active)
        if status is not None:
            existing["status"] = status
        if merged_into_asset_id is not None:
            existing["merged_into_asset_id"] = merged_into_asset_id.strip()
        existing["updated_at"] = now_iso

        # Re-check is_active constraint after updates
        if existing.get("is_active") is True and existing.get("status") != "active":
            _append_log("error", error_code="VALIDATION_ERROR", asset_id=existing.get("id"))
            return _err("VALIDATION_ERROR", "is_active=true requires status='active'")

        _save("crypto_assets.json", assets)
        _append_log("ok", asset_id=existing.get("id"))
        return {"data": existing, "created": False}

