        return e
    observed_norm = obs_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    # Validate numeric constraints
    for val, field in (
        (price, "price"),
        (market_cap, "market_cap"),
        (volume_24h, "volume_24h"),
        (high_24h, "high_24h"),
        (low_24h, "low_24h"),
    ):
