        if ee:
            _append_log("error", error_code="VALIDATION_ERROR")
            return ee
    for val, field in (
        (price_change_24h, "price_change_24h"),
        (price_change_pct_24h, "price_change_pct_24h"),
    ):
        if val is None:
            continue
        if not _is_num(val):
            _append_log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"{field} must be a number")

