            continue
        if r.get("asset_id") == asset_id and r.get("currency") == "USD" and r.get("observed_at") == observed_norm and r.get("source") == source:
            existing = r
            break

    transitions = {
        "partial": set(["complete", "error"]),
        "complete": set([]),
        "error": set([]),
    }

    if existing is None:
        if price is None:
            _append_log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "price is required when creating a snapshot")
        new_id = "cps_" + uuid.uuid4().hex
        row = {
            "id": new_id,
            "asset_id": asset_id,
            "currency": "USD",
            "observed_at": observed_norm,
            "source": source,
            "ingestion_status": ingestion_status,
