        _save("price_snapshots.json", rows)
        _append_log("ok", row_id=new_id)
        return {"data": row, "created": True}

    # Update existing: enforce lifecycle transitions
    cur = existing.get("ingestion_status")
    if ingestion_status != cur:
        if cur not in transitions or ingestion_status not in transitions[cur]:
            _append_log("error", error_code="INVALID_TRANSITION", row_id=existing.get("id"))
            return _err("INVALID_TRANSITION", "Illegal ingestion_status transition", from_status=cur, to_status=ingestion_status)

    # Upsert fields (do not allow nulling required fields)
    existing["currency"] = "USD"
    existing["observed_at"] = observed_norm
    existing["source"] = source
    existing["ingestion_status"] = ingestion_status
    if price is not None:
        existing["price"] = float(price) if _is_num(price) else price
    if market_cap is not None or "market_cap" in existing:
        existing["market_cap"] = market_cap
    if volume_24h is not None or "volume_24h" in existing:
        existing["volume_24h"] = volume_24h
    if price_change_24h is not None or "price_change_24h" in existing:
