    if price_change_pct_24h is not None or "price_change_pct_24h" in existing:
        existing["price_change_pct_24h"] = price_change_pct_24h
    if high_24h is not None or "high_24h" in existing:
        existing["high_24h"] = high_24h
    if low_24h is not None or "low_24h" in existing:
        existing["low_24h"] = low_24h
    existing["updated_at"] = now_iso

    _save("price_snapshots.json", rows)
    _append_log("ok", row_id=existing.get("id"))
    return {"data": existing, "created": False}

