        return None

    def _parse_dt(s, field):
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 datetime string")
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            else:
                dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt, None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 datetime string")

    def _is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def _validate_nonneg(x, field, required=False):
        if x is None:
            if required:
                return _err("VALIDATION_ERROR", f"{field} is required")
            return None
        if not _is_num(x):
            return _err("VALIDATION_ERROR", f"{field} must be a number")
        if x < 0:
            return _err("VALIDATION_ERROR", f"{field} must be >= 0")
        return None

    rl = _rate_limit_check()
    if rl is not None:
        _append_log("error", error_code="RATE_LIMIT")
        return rl

    if not isinstance(asset_id, str) or not asset_id.strip():
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "asset_id is required")
    if not isinstance(exchange_id, str) or not exchange_id.strip():
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "exchange_id is required")
    if not isinstance(currency, str) or not currency.strip():
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "currency is required")
    if currency != "USD":
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "currency must be 'USD'")
    if not isinstance(source, str) or not source.strip():
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "source is required")
    if not isinstance(status, str) or status not in ("valid", "superseded", "error"):
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of valid, superseded, error")

    obs_dt, e = _parse_dt(observed_at, "observed_at")
    if e:
        _append_log("error", error_code="VALIDATION_ERROR")
        return e
    observed_norm = obs_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    ee = _validate_nonneg(volume_24h, "volume_24h", required=(status == "valid"))
    if ee:
        _append_log("error", error_code="VALIDATION_ERROR")
        return ee
    ee = _validate_nonneg(liquidity_score, "liquidity_score", required=False)
    if ee:
        _append_log("error", error_code="VALIDATION_ERROR")
        return ee

    assets = _load("crypto_assets.json")
    if not isinstance(assets, list):
        assets = []
    if not any(isinstance(a, dict) and a.get("id") == asset_id for a in assets):
        _append_log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "asset_id not found", asset_id=asset_id)

    exchanges = _load("exchanges.json")
    if not isinstance(exchanges, list):
        exchanges = []
    if not any(isinstance(x, dict) and x.get("id") == exchange_id for x in exchanges):
        _append_log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "exchange_id not found", exchange_id=exchange_id)

    rows = _load("exchange_market_metrics.json")
    if not isinstance(rows, list):
        rows = []

    # Natural key: (asset_id, exchange_id, currency, observed_at, source)
    existing = None
    for r in rows:
        if not isinstance(r, dict):
            continue
        if (r.get("asset_id") == asset_id and r.get("exchange_id") == exchange_id and
            r.get("currency") == "USD" and r.get("observed_at") == observed_norm and r.get("source") == source):
            existing = r
            break

    transitions = {
        "valid": set(["superseded", "error"]),
        "superseded": set([]),
        "error": set([]),
    }

    if existing is None:
        if volume_24h is None:
            _append_log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "volume_24h is required when creating a metric row")
        new_id = "emm_" + uuid.uuid4().hex
        row = {
            "id": new_id,
            "asset_id": asset_id,
            "exchange_id": exchange_id,
            "currency": "USD",
            "observed_at": observed_norm,
            "source": source,
            "volume_24h": volume_24h,
            "liquidity_score": liquidity_score,
            "status": status,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        rows.append(row)
        _save("exchange_market_metrics.json", rows)
        _append_log("ok", row_id=new_id)
        return {"data": row, "created": True}

    cur = existing.get("status")
    if status != cur:
        if cur not in transitions or status not in transitions[cur]:
            _append_log("error", error_code="INVALID_TRANSITION", row_id=existing.get("id"))
            return _err("INVALID_TRANSITION", "Illegal status transition", from_status=cur, to_status=status)

    existing["currency"] = "USD"
    existing["observed_at"] = observed_norm
    existing["source"] = source
    existing["status"] = status
    if volume_24h is not None:
        existing["volume_24h"] = volume_24h
    if liquidity_score is not None or "liquidity_score" in existing:
        existing["liquidity_score"] = liquidity_score
    existing["updated_at"] = now_iso

    _save("exchange_market_metrics.json", rows)
    _append_log("ok", row_id=existing.get("id"))
    return {"data": existing, "created": False}
